import java.io.*;
import java.util.*;

public class CF1096G_Variant2 {
    static final int MODULUS = 998244353;
    static long[] wArr, wArrInv;
    static long modExp(int base, int exp) {
        long res = 1;
        long b = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1)
                res = (res * b) % MODULUS;
            b = (b * b) % MODULUS;
            e >>= 1;
        }
        return res;
    }
    static void prepare() {
        wArr = new long[21];
        wArrInv = new long[21];
        for (int h = 0; h <= 20; h++) {
            wArr[h] = modExp(3, (MODULUS - 1) >> h);
            wArrInv[h] = modExp(3, (MODULUS - 1) - ((MODULUS - 1) >> h));
        }
    }
    static void fftTransform(int[] data, int length, boolean invert) {
        for (int i = 1, j = 0; i < length; i++) {
            int mask = length;
            do
                j ^= mask >>= 1;
            while ((j & mask) == 0);
            if (i < j) {
                int temp = data[i]; data[i] = data[j]; data[j] = temp;
            }
        }
        for (int h = 0, size; (size = 1 << h) < length; h++) {
            long wFactor = invert ? wArrInv[h + 1] : wArr[h + 1];
            for (int start = 0; start < length; start += size * 2) {
                long w = 1;
                for (int j = 0; j < size; j++) {
                    int leftIdx = start + j, rightIdx = leftIdx + size;
                    long u = data[leftIdx], v = data[rightIdx] * w;
                    data[leftIdx] = (int)((u + v) % MODULUS);
                    data[rightIdx] = (int)((u - v + MODULUS) % MODULUS);
                    w = w * wFactor % MODULUS;
                }
            }
        }
    }
    public static void main(String[] args) throws IOException {
        prepare();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int nDiv2 = Integer.parseInt(st.nextToken()) / 2;
        int kCount = Integer.parseInt(st.nextToken());
        int nSize = 1;
        while (nSize < nDiv2 * 9 + 1)
            nSize <<= 1;
        int[] arr = new int[nSize];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < kCount; i++) {
            int d = Integer.parseInt(st.nextToken());
            arr[d] = 1;
        }
        fftTransform(arr, nSize, false);
        for (int i = 0; i < nSize; i++)
            arr[i] = (int) modExp(arr[i], nDiv2);
        fftTransform(arr, nSize, true);
        long invN = modExp(nSize, MODULUS - 2);
        long sumResult = 0;
        for (int i = 0; i < nSize; i++) {
            arr[i] = (int) (arr[i] * invN % MODULUS);
            if (arr[i] < 0)
                arr[i] += MODULUS;
        }
        for (int i = 0; i <= nDiv2 * 9; i++) {
            long val = arr[i];
            sumResult = (sumResult + val * val) % MODULUS;
        }
        System.out.println(sumResult);
    }
}
